def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_count += 1
        if opp.get('budget', 0) >= 700:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    scarcity = 1.0 - supply_ratio

    if hp <= 2 or no_water_days >= 2:
        target = max(DAILY_SALARY * 1.05, highest_prev + 4.0)
    elif hp <= 4 or no_water_days >= 1:
        target = max(DAILY_SALARY * 0.82, highest_prev + 2.0)
    else:
        if highest_prev >= 150:
            target = DAILY_SALARY * (0.38 + 0.12 * scarcity)
        elif highest_prev >= 100:
            target = max(DAILY_SALARY * (0.52 + 0.18 * scarcity), avg_prev * 0.78)
        elif highest_prev >= 70:
            target = max(DAILY_SALARY * (0.58 + 0.16 * scarcity), highest_prev + 1.5)
        else:
            target = DAILY_SALARY * (0.50 + 0.18 * scarcity)

    if urgent_count >= 2:
        target += 6.0
    elif urgent_count == 1:
        target += 3.0

    if rich_count >= 1 and highest_prev >= 140:
        target -= 4.0

    if day >= 8 and hp >= 5:
        target *= 0.92
    if day >= 9 and hp >= 7:
        target *= 0.88

    if budget < DAILY_SALARY * 2:
        target = min(target, budget * 0.72)
    elif budget < DAILY_SALARY * 4:
        target = min(target, budget * 0.55)

    floor_bid = 0.0
    if hp <= 4 or no_water_days >= 1:
        floor_bid = DAILY_SALARY * 0.45
    else:
        floor_bid = DAILY_SALARY * 0.22

    bid = max(floor_bid, target)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents, bid conservatively.
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer aggressiveness.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate aggressiveness and likely competition.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Target bid: aim to outbid the main threat (Cindy-like) only when supply is favorable.
    # Supply factor: when supply is high (near 25), more water is available so we can afford higher bids.
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_factor = 0.5
    if supply_factor < 0.0:
        supply_factor = 0.0
    if supply_factor > 1.0:
        supply_factor = 1.0

    # Base aggressiveness from yesterday's highest bid.
    # Cindy survived with low hp, so she likely bids to secure enough water.
    # We match her zone but with a slight discount to avoid overpaying.
    if highest_prev_bid >= DAILY_SALARY * 1.6:
        # Very aggressive field.
        target = highest_prev_bid * (0.92 - 0.15 * (1.0 - supply_factor))
    elif highest_prev_bid >= DAILY_SALARY * 1.2:
        # Moderate competition.
        target = highest_prev_bid * (0.85 - 0.10 * (1.0 - supply_factor))
    else:
        # Mostly conservative.
        target = max(DAILY_SALARY * 0.45, highest_prev_bid + 5.0)

    # HP-based escalation: if we are low, spend more to avoid running out of water days.
    no_water_days = int(my_status.get('no_water_days', 0))
    if my_hp <= 2 or no_water_days >= 2:
        target *= 1.25
    elif my_hp <= 3:
        target *= 1.10

    # Ensure we do not bid more than we can afford.
    # Also keep a floor so we don't get fully outcompeted when supply is high.
    min_bid_floor = DAILY_SALARY * (0.35 + 0.25 * supply_factor)
    if target < min_bid_floor:
        target = min_bid_floor

    # Final cap.
    bid = max(0.0, min(my_budget, float(target)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    is_desperate = False
    if my_status['hp'] <= 2:
        is_desperate = True
    elif my_status['no_water_days'] >= 1 and day_context['day'] > 1:
        is_desperate = True
    elif day_context['day'] >= EPISODE_DAYS - 2 and my_status['hp'] < 5:
        is_desperate = True

    if is_desperate:
        desperation_factor = (EPISODE_DAYS - day_context['day'] + 1) * 2
        bid = DAILY_SALARY * 0.95 + desperation_factor
        return min(my_status['budget'], max(1, bid))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.6

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            bid = highest_prev_bid + 5
        else:
            bid = max(base_bid, highest_prev_bid + 2)
    else:
        bid = base_bid + (day_context['day'] * 2)

    return min(my_status['budget'], max(1, bid))

def get_bid(day_context, my_status, opponents_status):
