    DAILY_SALARY = 140
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    alive_opps = [o for o in opponents_status.values() if o['alive']]
    if not alive_opps:
        return min(my_budget, 0.2 * DAILY_SALARY)
